 for j,x in enumerate(cells):C[x]=1<<j
 for b in range(t):
  for x in range(N):
   if x>>b&1:C[x]^=C[x^(1<<b)]
 B={}
 for s,row in enumerate(C):
  if sum(ns[i] for i in range(t) if s>>i&1)<=7:continue
  while row:
   p=row.bit_length()-1
